package in.foodcart.data; import org.springframework.data.mongodb.repository.MongoRepository; import java.util.*; public interface OrderRepository extends MongoRepository<OrderEntity,String>{List<OrderEntity> findByVendorIdOrderByCreatedAtDesc(String vendorId);List<OrderEntity> findByCustomerIdOrderByCreatedAtDesc(String customerId);List<OrderEntity> findByCustomerIdAndVendorIdOrderByCreatedAtDesc(String customerId,String vendorId);Optional<OrderEntity> findByIdAndVendorId(String id,String vendorId);List<OrderEntity> findByVendorIdAndStatusNotInOrderByCreatedAtDesc(String vendorId,Collection<in.foodcart.domain.OrderStatus> statuses);Optional<OrderEntity> findByPayment_GatewayOrderId(String gatewayOrderId);List<OrderEntity> findByStatusAndPayment_ExpiresAtBefore(in.foodcart.domain.OrderStatus status,java.time.Instant time);}
